    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.startPrank(address(this));
        c.initialize();
        c.transferOwnership(address(this));
        vm.stopPrank();
        vm.prank(address(this));
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
